import{_ as s,o as i,c as l,a2 as e}from"./chunks/framework.BXA5Pi9t.js";const P=JSON.parse('{"title":"A Hitchhikers Guide to Ceph RGW PubSub & Cats vs. Dogs - a Hybrid Cloud Storage Story","description":"","frontmatter":{"title":"A Hitchhikers Guide to Ceph RGW PubSub & Cats vs. Dogs - a Hybrid Cloud Storage Story","date":"2019-05-24T00:00:00.000Z","updated":"2019-05-24T00:00:00.000Z","tags":["Ceph","PubSub","混合云","云存储","分布式存储"],"categories":["技术文章"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/A_Hitchhiker_s_Guide_to_Ceph_RGW_PubSub_Cats_vs._Dogs_-_a_Hybrid_Cloud_Storage_Story.md","filePath":"posts/2019/A_Hitchhiker_s_Guide_to_Ceph_RGW_PubSub_Cats_vs._Dogs_-_a_Hybrid_Cloud_Storage_Story.md","lastUpdated":1780459816000}'),o={name:"posts/2019/A_Hitchhiker_s_Guide_to_Ceph_RGW_PubSub_Cats_vs._Dogs_-_a_Hybrid_Cloud_Storage_Story.md"};function r(_,t,a,n,u,p){return i(),l("div",null,[...t[0]||(t[0]=[e('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>： Ceph RGW PubSub 新功能介绍及混合云应用案例</p><p><strong>会议时间</strong>： 2023年X月X日</p><p><strong>参会人员</strong>： 未知</p><p><strong>会议内容</strong>：</p><p><strong>一、会议背景</strong></p><p>本次会议主要介绍了 Ceph RGW PubSub 的新功能，该功能已存在数月，并具有以下特点：</p><ul><li><strong>关键技术</strong>： Kubernetes、Canary、PUPs</li><li><strong>应用场景</strong>： 混合云、数据存储、事件发布/订阅</li></ul><p><strong>二、会议关键细节</strong></p><ol><li><strong>Kubernetes 与 Canary</strong>： <ul><li>Kubernetes 是一种容器编排平台，Canary 是 Kubernetes 中的一种框架，用于实现无服务器功能。</li><li>Ceph 利用 Kubernetes 的功能，实现了事件发布/订阅机制。</li></ul></li><li><strong>PUPs 功能介绍</strong>： <ul><li>PUPs 是 Ceph 中的事件发布/订阅机制，它允许用户将事件发布到不同的主题，并订阅感兴趣的事件。</li><li>PUPs 支持多种消息传递协议，包括 HTTP、AMQP、Kafka 等。</li></ul></li><li><strong>数据模型</strong>： <ul><li>主题：用于分类消息的术语，类似于 Kafka 和 AMQP。</li><li>订阅：将特定主题与存储桶关联，以便将事件推送到目标位置。</li><li>过滤器：允许用户订阅特定类型的事件，例如对象创建或删除。</li></ul></li><li><strong>混合云应用案例</strong>： <ul><li>会议演示了一个将图像分类算法部署在公共云上的案例。</li><li>当用户上传图像到 Ceph 存储桶时，PUPs 会将事件发布到主题，并触发相应的处理流程。</li><li>处理流程包括从 Ceph 获取图像、调用分类算法、将结果存储回 Ceph 等。</li></ul></li></ol><p><strong>三、讨论的主要议题</strong></p><ul><li>如何利用 PUPs 实现混合云应用？</li><li>如何在 Ceph 中集成其他消息传递协议？</li><li>如何优化 PUPs 的性能和可靠性？</li></ul><p><strong>四、决定的事项</strong></p><ul><li>未来将支持更多消息传递协议，例如 Kafka、ActiveMQ 等。</li><li>将考虑实现“推送模式”，以便直接将消息发送到外部系统。</li><li>将优化 PUPs 的性能和可靠性。</li></ul><p><strong>五、后续行动计划</strong></p><ul><li>完善文档，介绍 PUPs 的使用方法。</li><li>开发更多示例，展示 PUPs 在混合云中的应用。</li><li>优化 PUPs 的性能和可靠性。</li></ul><p><strong>六、其他</strong></p><ul><li>会议演示了如何使用 PUPs 实现图像分类，并展示了相关代码。</li><li>会议还讨论了如何将 PUPs 与其他技术（例如 Lambda 函数、服务函数等）集成。</li></ul><p><strong>关键词</strong>： Ceph、PUPs、Kubernetes、Canary、混合云、事件发布/订阅、消息传递协议</p>',19)])])}const d=s(o,[["render",r]]);export{P as __pageData,d as default};
